  Q("fin-rome", "personnage", "Quel empereur fait exécuter Stilicon alors que les Wisigoths sont en Italie ?", "Honorius", ["Dioclétien", "Auguste", "Alaric"], "Exemple des guerres internes de pouvoir qui affaiblissent l'empire.");
  Q("fin-rome", "lieu", "Où se forme le royaume vandale ?", "En Afrique", ["En Gaule", "En Hispanie", "En Italie"], "Royaumes germaniques : wisigoth en Gaule/Hispanie, vandale en Afrique, burgonde, suève…");
  C("fin-rome", "Remets ces événements dans l'ordre :", ["Les Goths entrent dans l'empire", "Alains, Suèves et Vandales franchissent le Rhin", "Sac de Rome par Alaric", "Prise de Carthage par les Vandales"], "376 Goths → 406 passage du Rhin → 410 sac de Rome → 439 Carthage.");

  // ─────────────── MÉROVINGIENS ET CAROLINGIENS ───────────────
  Q("francs", "date", "En quelle année Clovis devient-il roi des Francs ?", "481", ["486", "496", "511"], "481 : Clovis devient roi d'une partie des Francs.");
  Q("francs", "contexte", "Comment les Francs sont-ils organisés quand Clovis devient roi ?", "En plusieurs groupes et royaumes, chacun avec son roi", ["En une monarchie centralisée", "En provinces romaines", "En cités-États indépendantes"], "Ce n'est pas une monarchie centralisée : Clovis est chef d'une partie des Francs.");
  Q("francs", "personnage", "Qui dirige le royaume romain à l'ouest des Francs, autour de Soissons ?", "Syagrius", ["Alaric", "Stilicon", "Sigebert"], "À l'ouest des Francs : le royaume romain de Syagrius (Soissons).");
  Q("francs", "lieu", "Quelle est la capitale des Wisigoths en Gaule ?", "Toulouse", ["Lyon", "Soissons", "Tournai"], "Au sud-ouest, les Wisigoths ont Toulouse pour capitale.");
  Q("francs", "date", "En quelle année a lieu la bataille de Soissons ?", "486", ["481", "496", "507"], "486 : première grande conquête de Clovis, contre Syagrius.");
  Q("francs", "contexte", "Que devient Syagrius après sa défaite à Soissons ?", "Il fuit chez les Wisigoths, est remis à Clovis puis exécuté", ["Il devient allié de Clovis", "Il est baptisé à Reims", "Il part fonder un royaume en Afrique"], "Syagrius fuit à Toulouse, mais les Wisigoths le livrent à Clovis.");
  Q("francs", "lieu", "Contre qui Clovis se bat-il à Tolbiac ?", "Les Alamans", ["Les Wisigoths", "Les Burgondes", "Les Romains de Syagrius"], "496 : bataille de Tolbiac contre les Alamans.");
  Q("francs", "personnage", "Selon quel auteur Clovis aurait-il promis de se convertir s'il gagnait à Tolbiac ?", "Grégoire de Tours", ["L'évêque Rémi", "Sainte Geneviève", "Le pape Zacharie"], "Selon Grégoire de Tours, en difficulté à Tolbiac, Clovis promet à Dieu sa conversion.");
  Q("francs", "lieu", "Où Clovis est-il baptisé ?", "À Reims", ["À Paris", "À Soissons", "À Tours"], "Baptême de Clovis à Reims par l'évêque Rémi.");
  Q("francs", "personnage", "Qui baptise Clovis ?", "L'évêque Rémi", ["Grégoire de Tours", "Le pape Zacharie", "Clotilde"], "Clovis est baptisé à Reims par l'évêque Rémi.");
  Q("francs", "personnage", "Quelle épouse de Clovis, princesse burgonde catholique, aurait joué un rôle dans sa conversion ?", "Clotilde", ["Geneviève", "Blanche de Castille", "Aliénor"], "Clotilde, princesse burgonde catholique.");
  Q("francs", "contexte", "Pourquoi le baptême catholique de Clovis est-il important politiquement ?", "Il le rapproche de l'Église et des Gallo-Romains, alors que les autres rois germaniques sont ariens", ["Il lui permet de devenir empereur", "Il lui donne le soutien des Perses", "Il met fin aux guerres contre les Wisigoths"], "Les autres rois germaniques avaient adopté l'arianisme.");
  Q("francs", "lieu", "Quelle bataille de 500 voit Clovis intervenir chez les Burgondes, sans conquérir leur royaume ?", "Dijon", ["Vouillé", "Tolbiac", "Tertry"], "Bataille de Dijon : Clovis gagne mais ne conquiert pas la Burgondie.");
  Q("francs", "date", "En quelle année les fils de Clovis conquièrent-ils la Burgondie ?", "534", ["500", "511", "558"], "Ce sont les fils de Clovis qui conquièrent la Burgondie en 534.");
  Q("francs", "lieu", "Quelle bataille de 507 permet à Clovis de prendre l'Aquitaine aux Wisigoths ?", "Vouillé", ["Tolbiac", "Soissons", "Poitiers"], "507 : Vouillé, Clovis prend Toulouse et l'Aquitaine.");
  Q("francs", "date", "En quelle année Clovis fait-il de Paris sa capitale ?", "508", ["481", "496", "511"], "508 : Paris devient capitale.");
  Q("francs", "contexte", "Pourquoi Clovis choisit-il Paris comme capitale ?", "Ville prestigieuse, stratégique grâce à la Seine, protégée par sainte Geneviève", ["C'est la ville où il est né", "C'est la capitale de Syagrius", "Le pape la lui a donnée"], "Ville déjà prestigieuse, stratégique pour les déplacements grâce à la Seine.");
  Q("francs", "personnage", "Quel roi des Francs ripuaires de Cologne Clovis fait-il éliminer ?", "Sigebert", ["Syagrius", "Clotaire", "Alaric"], "Clovis fait tuer les rois francs concurrents : Sigebert, Ragnacaire, Chararic.");
  Q("francs", "date", "En quelle année meurt Clovis ?", "511", ["508", "534", "558"], "511 : mort de Clovis, partage du royaume entre ses fils.");
  Q("francs", "personnage", "Sous quel roi le royaume franc est-il réunifié en 558 ?", "Clotaire Ier", ["Clotaire II", "Pépin le Bref", "Charles Martel"], "558 : réunification sous Clotaire Ier.");
  Q("francs", "contexte", "Quels royaumes s'opposent pendant les grandes faides (567-613) ?", "Neustrie et Austrasie", ["Burgondie et Aquitaine", "Francie occidentale et orientale", "Normandie et Anjou"], "Les faides opposent Neustrie et Austrasie, avant la réunification sous Clotaire II.");
  Q("francs", "contexte", "Quel personnage prend de plus en plus de pouvoir sous les Mérovingiens ?", "Le maire du palais", ["L'évêque de Reims", "Le prévôt de Paris", "L'archonte"], "Le maire du palais gère administration, finances, aristocratie et armée.");
  Q("francs", "lieu", "Quelle bataille de 687 marque le tournant où les Pippinides prennent le pouvoir ?", "Tertry", ["Poitiers", "Vouillé", "Dijon"], "687 : Tertry, Pépin de Herstal domine la Neustrie.");
  Q("francs", "personnage", "Qui impose sa domination sur la Neustrie à Tertry en 687 ?", "Pépin de Herstal", ["Pépin de Landen", "Pépin le Bref", "Charles Martel"], "Pépin de Herstal : les Mérovingiens restent rois mais les Pippinides ont le pouvoir.");
  Q("francs", "personnage", "Qui gagne la bataille de Poitiers en 732 ?", "Charles Martel", ["Clovis", "Pépin le Bref", "Charlemagne"], "732 : Charles Martel, pas roi, mais il dirige le royaume.");
  Q("francs", "date", "En quelle année Pépin le Bref dépose-t-il le dernier roi mérovingien ?", "751", ["732", "768", "800"], "751 : début des Carolingiens.");
  Q("francs", "personnage", "Quel pape soutient Pépin le Bref quand il prend le pouvoir ?", "Zacharie", ["Boniface VIII", "Clément V", "Rémi"], "Pépin le Bref dépose le dernier Mérovingien avec l'appui du pape Zacharie.");
  Q("francs", "contexte", "Quel peuple Charlemagne soumet-il en 782, avec le massacre de Verden ?", "Les Saxons", ["Les Lombards", "Les Avars", "Les Alamans"], "773 : Lombards ; 782 : Saxons (massacre de Verden).");
  Q("francs", "date", "En quelle année Charlemagne devient-il empereur d'Occident ?", "800", ["768", "814", "843"], "800 : résurrection de l'Empire romain en Occident.");
  Q("francs", "date", "En quelle année meurt Charlemagne ?", "814", ["800", "843", "768"], "Charlemagne meurt en 814 ; ses fils se disputent l'héritage.");
  Q("francs", "contexte", "Que décide le traité de Verdun (843) ?", "Le partage de l'empire, avec la Francie occidentale et la Francie orientale", ["La fin des Mérovingiens", "Le couronnement de Charlemagne", "La création de la Normandie"], "843 : traité de Verdun, partage entre les héritiers de Charlemagne.");
  C("francs", "Remets ces batailles de Clovis dans l'ordre :", ["Soissons", "Tolbiac", "Dijon", "Vouillé"], "486 Soissons → 496 Tolbiac → 500 Dijon → 507 Vouillé.");
  C("francs", "Remets ces événements dans l'ordre :", ["Bataille de Tertry", "Bataille de Poitiers", "Pépin le Bref devient roi", "Charlemagne empereur"], "687 Tertry → 732 Poitiers → 751 Pépin le Bref → 800 Charlemagne empereur.");

  // ─────────────── CAPÉTIENS ───────────────
  Q("capetiens", "date", "En quelle année un territoire est-il donné à Rollon, chef viking ?", "911", ["987", "843", "1066"], "911 : naissance de la Normandie.");
  Q("capetiens", "personnage", "Quel chef viking reçoit le territoire qui deviendra la Normandie ?", "Rollon", ["Guillaume le Conquérant", "Robert Courteheuse", "Harold II"], "911 : un territoire est donné à Rollon.");
