  Q("capetiens", "contexte", "Pourquoi Guillaume revendique-t-il l'Angleterre en 1066 ?", "Le roi Édouard le Confesseur meurt sans héritier", ["Le roi d'Angleterre l'a attaqué", "Le pape lui a donné le trône", "Il a épousé la reine d'Angleterre"], "À la mort d'Édouard le Confesseur, sans héritier.");
  Q("capetiens", "personnage", "Qui réunifie l'Angleterre et la Normandie en 1106 ?", "Henri Ier, 3e fils de Guillaume", ["Guillaume II", "Robert Courteheuse", "Henri II Plantagenêt"], "1106 : Henri réunifie les deux et devient Henri Ier.");
  Q("capetiens", "contexte", "D'où vient le nom « Plantagenêt » ?", "De Planta genista, le genêt, emblème de Geoffroy V d'Anjou", ["D'une ville d'Anjou", "Du nom de la mère d'Henri II", "D'une bataille contre les Capétiens"], "Planta genista : la plante de genêt, emblème du père d'Henri II.");
  Q("capetiens", "date", "En quelle année Henri II Plantagenêt prend-il le trône d'Angleterre ?", "1154", ["1152", "1135", "1189"], "1154, après les guerres de succession de 1135-1154.");
  Q("capetiens", "contexte", "Comment Henri II Plantagenêt obtient-il l'Aquitaine ?", "Par son mariage avec Aliénor en 1152", ["Par la bataille de Bouvines", "Par le traité de Paris", "En l'achetant au roi de France"], "Il épouse Aliénor d'Aquitaine en 1152.");
  Q("capetiens", "personnage", "Quel roi d'Angleterre règne de 1189 à 1199 ?", "Richard Cœur de Lion", ["Jean sans Terre", "Henri II", "Henri III"], "1189-1199 : Richard Cœur de Lion, puis Jean sans Terre.");
  Q("capetiens", "contexte", "À l'arrivée de Louis VI le Gros, que comprend le domaine royal ?", "Seulement Paris et Orléans", ["Toute la France actuelle", "La Normandie et l'Anjou", "L'Aquitaine"], "Le domaine royal est très petit : Paris et Orléans.");
  Q("capetiens", "contexte", "Quel changement Louis VI le Gros apporte-t-il au rôle du roi ?", "Le roi devient un seigneur supérieur capable d'intervenir dans le royaume", ["Le roi est désormais élu par le peuple", "Le roi n'a plus besoin des seigneurs", "Le roi devient empereur"], "Il intervient dans les conflits entre seigneurs et affirme son autorité.");
  Q("capetiens", "personnage", "Qui Louis VII épouse-t-il en 1137 ?", "Aliénor d'Aquitaine", ["Blanche de Castille", "Isabelle de France", "Clotilde"], "Louis VII et Aliénor divorcent en 1152 ; elle épouse alors Henri Plantagenêt.");
  Q("capetiens", "date", "En quelle année Louis VII et Aliénor d'Aquitaine divorcent-ils ?", "1152", ["1137", "1154", "1180"], "Divorce en 1152, la même année que le mariage d'Aliénor avec Henri Plantagenêt.");
