  Q("capetiens", "personnage", "Quel pape, installé à Avignon, supprime l'ordre du Temple en 1312 ?", "Clément V", ["Boniface VIII", "Zacharie", "Grégoire de Tours"], "Clément V (à Avignon depuis 1309) supprime définitivement l'ordre en 1312.");
  Q("capetiens", "personnage", "Quel grand maître des Templiers est exécuté à Paris en 1314 ?", "Jacques de Molay", ["Étienne Marcel", "Bertrand du Guesclin", "Jean sans Peur"], "Jacques de Molay est exécuté à Paris en 1314.");
  Q("capetiens", "personnage", "Qui Philippe le Bel marie-t-il à Édouard II d'Angleterre pour apaiser les tensions ?", "Sa fille Isabelle de France", ["Blanche de Castille", "Aliénor d'Aquitaine", "Sa sœur Marguerite"], "1308 : mariage d'Isabelle de France et d'Édouard II.");
  Q("capetiens", "personnage", "Qui les seigneurs choisissent-ils comme roi en 1328 ?", "Philippe VI de Valois", ["Édouard III", "Jean II le Bon", "Louis X"], "Philippe VI de Valois, d'une branche cousine.");
  Q("capetiens", "contexte", "Pourquoi Édouard III revendique-t-il la couronne de France ?", "Il est le petit-fils de Philippe IV le Bel", ["Il a épousé l'héritière du trône", "Il a gagné la bataille de Crécy", "Le pape l'a désigné"], "Édouard III est le petit-fils de Philippe IV par sa mère, Isabelle de France.");
  Q("capetiens", "date", "En quelle année commence la guerre de Cent Ans ?", "1337", ["1328", "1346", "1314"], "1337 : début de la guerre de Cent Ans.");
